import js from "@eslint/js";
import prettier from "eslint-config-prettier";
import reactHooks from "eslint-plugin-react-hooks";
import reactRefresh from "eslint-plugin-react-refresh";
import globals from "globals";
import tseslint from "typescript-eslint";

/**
 * ESLint flat config (`npm run lint`).
 *
 * Correctness only — formatting is Prettier's job, so `eslint-config-prettier`
 * goes last to switch off every stylistic rule it would fight over.
 *
 * `src/routeTree.gen.ts` is generated by the TanStack Router plugin on every
 * dev/build run: it carries `@ts-nocheck` and must never be edited or linted.
 */
export default tseslint.config(
  {
    ignores: ["dist/**", ".output/**", ".nitro/**", "node_modules/**", "src/routeTree.gen.ts"],
  },
  {
    files: ["**/*.{ts,tsx}"],
    extends: [js.configs.recommended, ...tseslint.configs.recommended],
    languageOptions: {
      ecmaVersion: 2022,
      // Both runtimes appear in one file: client components AND the server
      // functions/loaders the same modules call, plus Node-side `process`.
      globals: { ...globals.browser, ...globals.node },
    },
    plugins: {
      "react-hooks": reactHooks,
      "react-refresh": reactRefresh,
    },
    rules: {
      ...reactHooks.configs.recommended.rules,
      "react-refresh/only-export-components": "warn",
    },
  },
  {
    files: ["scripts/**/*.mjs", "*.{js,mjs}"],
    extends: [js.configs.recommended],
    languageOptions: {
      ecmaVersion: 2022,
      sourceType: "module",
      // The Playwright scripts hand `page.evaluate` bodies to Chromium, so a
      // `document`/`window` reference there is the browser's, not a mistake.
      globals: { ...globals.node, ...globals.browser },
    },
  },
  prettier,
);
